require_once __DIR__ . '/../support/DoajPaRuleFixture.inc.php';
require_once __DIR__ . '/../../classes/persistence/DoajPaSchema.inc.php';
require_once __DIR__ . '/../../classes/framework/DoajPaRuleRegistry.inc.php';

function s3_ctx($site, $opts = array()) {
	return DoajPaRuleFixture::context(DoajPaRuleFixture::pages($site), $opts + array('site' => $site));
}
function s3_eval($site, $opts = array()) {
	static $cache = array();
	$k = $site . json_encode($opts);
	if (!isset($cache[$k])) { $c = s3_ctx($site, $opts); $cache[$k] = array($c, DoajPaRuleFixture::evaluate($c)); }
	return $cache[$k];
}
function s3_specs() {
	$d = DoajPaCandidateDataset::data();
	$out = array();
	foreach ($d['criteria'] as $c) $out[$c['key']] = $c;
	return $out;
}
function s3_status($o, $key) { return $o[$key]['status']; }
function s3_page($html, $title = 'Page') {
	return '<!DOCTYPE html><html lang="en"><head><title>' . $title . '</title></head><body><div class="pkp_structure_page"><header class="pkp_structure_head" role="banner">'
		. '<div class="pkp_site_name"><a>Test Journal</a></div><nav class="pkp_site_nav_menu"><a href="/about">About the journal and the policies of the journal</a></nav></header>'
		. '<div class="pkp_structure_content"><div class="pkp_structure_main" role="main">' . $html . '</div></div>'
		. '<div class="pkp_structure_footer_wrapper" role="contentinfo"><p>Footer text of the journal website.</p></div></div></body></html>';
}
const S3_EN = 'The journal publishes research articles about education and it is read by teachers and researchers in many countries. The editors of the journal select the articles that are published in each issue, and the authors of the articles are researchers at universities and schools. ';

//
// Text utilities
