doajpa_test('S3-T01 Text: sentences are verbatim substrings; negated matches are skipped only when asked', function () {
	$t = "Open access policy.\nThe journal does not charge fees. Authors retain copyright (CC BY 4.0).";
	foreach (DoajPaText::sentences($t) as $s) doajpa_assert(strpos($t, $s) !== false, 'verbatim: ' . $s);
	$e = array(array('id' => 1, 'quote' => $t, 'verifiedEnglish' => true));
	doajpa_same(1, count(DoajPaText::find($e, '/\bcharge\b/')), 'match without negation filter');
	doajpa_same(0, count(DoajPaText::find($e, '/\bcharge\b/', true)), 'negated match skipped');
	doajpa_same(300, mb_strlen(DoajPaText::snippet(str_repeat('word ', 200), 500), 'UTF-8'), 'snippet capped at MAX_QUOTE');
});
doajpa_test('S3-T02 Text: person names match only on the full name; initials and partial names are ambiguous, never confirmed', function () {
	doajpa_same('confirmed', DoajPaText::nameMatch('Prof. Maria Lopez', 'Maria Lopez, PhD'), 'titles and degrees ignored');
	doajpa_same('confirmed', DoajPaText::nameMatch('Lopez Maria', 'Maria Lopez'), 'same token set');
	doajpa_same('ambiguous', DoajPaText::nameMatch('M. Lopez', 'Maria Lopez'), 'initial');
	doajpa_same('ambiguous', DoajPaText::nameMatch('Maria A. Lopez', 'Maria Lopez'), 'middle initial');
	doajpa_same('none', DoajPaText::nameMatch('Mario Lopez', 'Maria Lopez'), 'different first name');
	doajpa_same('none', DoajPaText::nameMatch('Lopez', 'Maria Lopez'), 'single token never matches');
	doajpa_same('confirmed', DoajPaText::nameMatch('José Pérez', 'Jose Perez'), 'diacritics folded');
});
doajpa_test('S3-T03 Text: dates parse deterministically; day/month order that cannot be told apart is ambiguous', function () {
	doajpa_same('2024-06-30', DoajPaText::parseDate('2024-06-30')['date'], 'ISO');
	doajpa_same('2024-06-30', DoajPaText::parseDate('30 June 2024')['date'], 'day month year');
	doajpa_same('2024-06-30', DoajPaText::parseDate('June 30, 2024')['date'], 'month day year');
	doajpa_same('2024-06-30', DoajPaText::parseDate('30/06/2024')['date'], 'unambiguous numeric');
	doajpa_same('ambiguous', DoajPaText::parseDate('03/04/2024')['status'], 'ambiguous numeric');
	doajpa_same('invalid', DoajPaText::parseDate('2024-02-30')['status'], 'impossible date');
	doajpa_same('invalid', DoajPaText::parseDate('soon')['status'], 'no date');
});
doajpa_test('S3-T04 Text: ISSN check digit', function () {
	doajpa_assert(DoajPaText::issnValid('2049-3630') && DoajPaText::issnValid('2049-3649') && DoajPaText::issnValid('0378-5955'), 'valid');
	doajpa_assert(!DoajPaText::issnValid('2049-3631') && !DoajPaText::issnValid('1234-5678') && !DoajPaText::issnValid('2049 3630'), 'invalid');
});

