doajpa_test('S3-E01 Extractor: OJS 3.3 main region excludes header, navigation, breadcrumbs, sidebar and footer', function () {
	$p = DoajPaRuleFixture::pages('good');
	$x = DoajPaHtmlExtractor::extract($p['/about'][1], 'utf-8', 'http://fixtures:8080/s3/index.php/good/about');
	doajpa_same('role-main', $x['mainRegion'], 'region');
	doajpa_assert(strpos($x['mainText'], 'Focus and Scope') !== false, 'main content kept');
	foreach (array('Archives', 'You are here', 'Information', 'Print ISSN', 'Platform and workflow') as $chrome) {
		doajpa_assert(strpos($x['mainText'], $chrome) === false, 'chrome removed from main: ' . $chrome);
	}
	doajpa_assert(strpos($x['text'], 'Print ISSN: 2049-3630') !== false, 'whole-page text keeps the sidebar');
	doajpa_assert(in_array('site-name: Journal of Open Education Research', $x['structured'], true), 'site name');
	doajpa_assert((bool) preg_grep('#^licence-link: https://creativecommons.org/licenses/by/4.0/ \| #', $x['structured']), 'licence link');
	$i = DoajPaHtmlExtractor::extract($p['/issue/view/3'][1], 'utf-8', 'http://fixtures:8080/s3/index.php/good/issue/view/3');
	$toc = preg_grep('/^toc \| /', $i['structured']);
	doajpa_same(5, count($toc), 'toc entries');
	doajpa_assert(in_array('toc | Articles | Peer feedback in online writing courses | Thomas Becker, Sara Lindqvist | http://fixtures:8080/s3/index.php/good/article/view/8', $i['structured'], true), 'toc line with section, authors and URL');
});
doajpa_test('S3-E02 ADR-011: language comes from the main region; navigation and sidebars do not decide it; short text stays undetermined', function () {
	$id = str_repeat('Jurnal ini menerbitkan artikel penelitian yang telah ditelaah oleh mitra bestari dan dapat diakses secara terbuka oleh semua pembaca tanpa biaya. ', 4);
	$sideEn = '<div class="pkp_structure_sidebar" role="complementary"><p>' . str_repeat(S3_EN, 3) . '</p></div>';
	$pages = array(
		'/about' => array('html', str_replace('</div></div><div class="pkp_structure_footer_wrapper"', '</div>' . $sideEn . '</div><div class="pkp_structure_footer_wrapper"', s3_page('<p>' . $id . '</p>'))),
		'/about/submissions' => array('html', str_replace('</div></div><div class="pkp_structure_footer_wrapper"', '</div><div class="pkp_structure_sidebar" role="complementary"><p>' . $id . $id . '</p></div></div><div class="pkp_structure_footer_wrapper"', s3_page('<p>' . S3_EN . S3_EN . '</p>'))),
		'/about/contact' => array('html', s3_page('<p>Contact: editor@example.org</p>')),
	);
	$c = DoajPaRuleFixture::context($pages, array('site' => 'lang'));
	$lang = array();
	foreach ($c->evidence() as $e) if ($e['method'] === 'html_main_content') $lang[$e['pageType']] = array($e['language'], $e['verifiedEnglish']);
	doajpa_same(array('non_english', false), $lang['about'], 'Indonesian main content with an English sidebar is not English');
	doajpa_same(array('english', true), $lang['author_guidelines'], 'English main content with an Indonesian sidebar is English');
	doajpa_same(array('undetermined', false), $lang['contact'], 'too little main text stays undetermined');
});

//
// Outcome guard: absence / observation basis (ADR-010 R1.8)
//

doajpa_test('S3-G01 Guard: absence/observation pass needs cited, verified-English evidence; never upgrades; quote basis still needs a quote', function () {
	$ev = array(1 => array('quote' => S3_EN, 'verifiedEnglish' => true), 2 => array('quote' => 'Kontak', 'verifiedEnglish' => false));
	doajpa_same('pass', DoajPaOutcomeGuard::apply(array('status' => 'pass', 'basis' => 'absence', 'evidenceIds' => array(1)), $ev, 'k')['status'], 'absence on verified page');
	doajpa_same('pass', DoajPaOutcomeGuard::apply(array('status' => 'pass', 'basis' => 'observation', 'evidenceIds' => array(1)), $ev, 'k')['status'], 'observation');
	doajpa_same('unverifiable', DoajPaOutcomeGuard::apply(array('status' => 'pass', 'basis' => 'absence', 'evidenceIds' => array()), $ev, 'k')['status'], 'nothing cited');
	doajpa_same('unverifiable', DoajPaOutcomeGuard::apply(array('status' => 'pass', 'basis' => 'absence', 'evidenceIds' => array(1, 2)), $ev, 'k')['status'], 'one cited page unverified');
	doajpa_same('unverifiable', DoajPaOutcomeGuard::apply(array('status' => 'pass', 'basis' => 'absence', 'evidenceIds' => array(9)), $ev, 'k')['status'], 'foreign evidence');
	doajpa_same('unverifiable', DoajPaOutcomeGuard::apply(array('status' => 'pass', 'basis' => 'quote', 'evidenceIds' => array(1)), $ev, 'k')['status'], 'quote basis without quote');
	doajpa_same('unverifiable', DoajPaOutcomeGuard::apply(array('status' => 'pass', 'basis' => 'whatever', 'evidenceIds' => array(1)), $ev, 'k')['status'], 'unknown basis is the quote basis');
	doajpa_same('unverifiable', DoajPaOutcomeGuard::apply(array('status' => 'unverifiable', 'basis' => 'absence', 'evidenceIds' => array(1)), $ev, 'k')['status'], 'never upgraded');
});

//
