doajpa_test('S3-D01 Dataset: generated PHP copy matches the proposed JSON; status proposed; the proposed version itself is never approved', function () {
	$src = __DIR__ . '/../../docs/stage03/criteria/doaj-criteria-0.1.0-draft.json';
	if (!is_file($src)) { doajpa_assert(true, 'criteria source is internal (not in the public repository): skipped'); return; }
	$json = file_get_contents($src);
	doajpa_same(hash('sha256', $json), DoajPaCandidateDataset::SOURCE_SHA256, 'source hash');
	$j = json_decode($json, true);
	$d = DoajPaCandidateDataset::data();
	doajpa_same(count($j['criteria']), count($d['criteria']), 'criteria count');
	doajpa_same(137, count($d['criteria']), '137 criteria');
	doajpa_same('proposed', DoajPaCandidateDataset::STATUS, 'status');
	doajpa_same(null, $d['dataset']['approvedBy'], 'no approver');
	foreach ($j['criteria'] as $i => $c) {
		foreach (array('key', 'quote', 'level', 'evidence', 'assessability', 'abstainWhen', 'doajReferenceUrl') as $f) doajpa_same($c[$f], $d['criteria'][$i][$f], $c['key'] . ' ' . $f);
	}
	doajpa_assert(!in_array(DoajPaCandidateDataset::VERSION, DoajPaSchema::APPROVED_DATASETS, true), 'the proposed version is never approved');
	doajpa_assert(!in_array(DoajPaSchema::CANDIDATE_RULEBOOK, DoajPaSchema::APPROVED_RULEBOOKS, true), 'candidate rulebook is never approved');
	doajpa_same('candidate-doajpa-criteria-' . DoajPaCandidateDataset::VERSION, DoajPaSchema::CANDIDATE_RULEBOOK, 'rulebook label names the dataset');
	doajpa_same(20, count($d['fqMapping']), 'FQ mapping');
});
doajpa_test('S3-D02 Candidate rules: one rule per criterion, valid metadata, a dedicated handler for every key', function () {
	$rules = DoajPaRuleRegistry::candidateRules();
	doajpa_same(137, count($rules), 'rules');
	$keys = array();
	foreach ($rules as $r) {
		doajpa_assert($r instanceof DoajPaCriterionRule, 'interface');
		doajpa_assert(preg_match('/^[a-z0-9][a-z0-9_.-]{0,63}$/', $r->key()) === 1, 'key ' . $r->key());
		doajpa_same(array(1, 1), array($r->version(), $r->lineage()), 'candidate version/lineage ' . $r->key());
		doajpa_assert(in_array($r->level(), DoajPaSchema::LEVELS, true), 'level');
		doajpa_assert(in_array($r->doajReferenceUrl(), array('https://doaj.org/apply/guide/', 'https://doaj.org/apply/transparency/', 'https://doaj.org/apply/copyright-and-licensing/'), true), 'reference url');
		doajpa_assert(mb_strlen($r->title(), 'UTF-8') <= 255 && strlen($r->sourceVersion()) <= 64 && $r->sourceVersion() !== '', 'title/source lengths');
		doajpa_assert(method_exists('DoajPaChecks', 'c_' . str_replace(array('.', '-'), '_', $r->key())), 'handler for ' . $r->key());
		$keys[$r->key()] = true;
	}
	doajpa_same(137, count($keys), 'unique keys');
});

