doajpa_test('S3-P01 Every outcome is valid and survives the guard unchanged (no fabricated quote, no foreign evidence)', function () {
	foreach (array('good', 'bad', 'foreign') as $site) {
		list($c, $o) = s3_eval($site);
		doajpa_same(137, count($o), $site . ' outcomes');
		foreach ($o as $k => $x) {
			doajpa_assert(in_array($x['status'], DoajPaSchema::CRITERION_STATUSES, true), "$site $k status");
			doajpa_same(array(), $x['downgrades'], "$site $k downgrades");
			doajpa_assert($x['rationale'] !== '' && $x['interpretationLimit'] !== '', "$site $k rationale");
		}
	}
});
doajpa_test('S3-P02 A pass always rests on verified-English evidence (or, basis "neutral" only, neutral-eligible evidence, ADR-013): a verbatim quote, or a declared absence/observation basis', function () {
	foreach (array('good', 'bad', 'foreign') as $site) {
		list($c, $o) = s3_eval($site);
		$neutral = $c->neutralEligible();
		foreach ($o as $k => $x) {
			if ($x['status'] !== 'pass') continue;
			doajpa_assert($x['evidenceIds'] !== array(), "$site $k cites evidence");
			foreach ($x['evidenceIds'] as $id) doajpa_assert($c->evidenceById($id)['verifiedEnglish'] || ($x['basis'] === 'neutral' && $neutral[$id]), "$site $k cites verified English (or neutral-eligible evidence with basis neutral)");
			if ($x['basis'] === 'neutral') doajpa_same(array(), $x['verifiedClear'], "$site $k: a neutral fact never resolves a finding");
			if (!in_array($x['basis'], array('absence', 'observation'), true)) {
				doajpa_assert($x['quotes'] !== array(), "$site $k has a quote");
				foreach ($x['quotes'] as $q) doajpa_assert(strpos($c->evidenceById($q['evidenceId'])['quote'], $q['text']) !== false, "$site $k quote verbatim");
			}
		}
	}
});
doajpa_test('S3-P03 Level bounds: H and human-only never pass or fail; R never fails; external-registry criteria never pass', function () {
	$spec = s3_specs();
	foreach (array('good', 'bad', 'foreign') as $site) {
		list($c, $o) = s3_eval($site);
		foreach ($o as $k => $x) {
			if ($spec[$k]['level'] === 'H' || $spec[$k]['assessability'] === 'human') doajpa_assert(!in_array($x['status'], array('pass', 'fail', 'warning'), true), "$site $k human");
			if ($spec[$k]['level'] === 'R') doajpa_assert($x['status'] !== 'fail', "$site $k recommendation never fails");
			if ($spec[$k]['assessability'] === 'external') doajpa_assert($x['status'] !== 'pass', "$site $k external");
		}
	}
	$o = DoajPaChecks::bound(array('level' => 'H', 'assessability' => 'human'), array('status' => 'pass', 'rationale' => 'x', 'detections' => array(), 'verifiedClear' => array()));
	doajpa_same('for_doaj_review', $o['status'], 'bound H');
	$o = DoajPaChecks::bound(array('level' => 'R', 'assessability' => 'partial'), array('status' => 'fail', 'rationale' => 'x', 'detections' => array(array('criterionStatus' => 'fail')), 'verifiedClear' => array()));
	doajpa_same(array('warning', 'warning'), array($o['status'], $o['detections'][0]['criterionStatus']), 'bound R');
	$o = DoajPaChecks::bound(array('level' => 'M', 'assessability' => 'external'), array('status' => 'pass', 'rationale' => 'x', 'detections' => array(), 'verifiedClear' => array(1)));
	doajpa_same('unverifiable', $o['status'], 'bound external');
});
doajpa_test('S3-P04 Every fail, warning and contradiction carries a corrective recommendation with the DOAJ clause and a detection', function () {
	foreach (array('good', 'bad') as $site) {
		list($c, $o) = s3_eval($site);
		foreach ($o as $k => $x) {
			if (!in_array($x['status'], array('fail', 'warning', 'contradiction'), true)) continue;
			doajpa_assert(strpos($x['rationale'], 'Recommended correction: ') !== false && strpos($x['rationale'], '(DOAJ: "') !== false, "$site $k recommendation");
			doajpa_assert($x['detections'] !== array(), "$site $k detection");
			foreach ($x['detections'] as $d) doajpa_same($x['status'], $d['criterionStatus'], "$site $k detection status");
		}
	}
});
doajpa_test('S3-P05 Deterministic: the same evidence gives the same outcomes and FQ answers', function () {
	$a = DoajPaRuleFixture::evaluate(s3_ctx('bad'));
