});
doajpa_test('S3-P06 Empty evidence: no exception, no pass, fail, warning or contradiction', function () {
	$c = new DoajPaEvaluationContext(array(), array(), array('finishedAtUtc' => DoajPaRuleFixture::FINISHED, 'limitsHit' => array()));
