doajpa_test('S3-R01 Conforming journal: the 29 proposed first-wave must-criteria pass with quoted evidence', function () {
	list($c, $o) = s3_eval('good');
	$wave = array('guide.actively-publishing', 'guide.five-research-articles-per-year', 'guide.oa-only', 'guide.oa-statement', 'guide.oa-full-text-without-delay',
		'guide.no-embargo', 'guide.no-registration-to-read', 'guide.dedicated-homepage', 'guide.article-individual-full-text', 'guide.article-unique-url',
		'guide.article-html-or-pdf', 'guide.disclosure-oa-policy', 'guide.disclosure-aims-scope', 'guide.disclosure-editorial-board',
		'guide.disclosure-author-instructions', 'guide.disclosure-peer-review', 'guide.disclosure-licensing', 'guide.disclosure-copyright',
		'guide.disclosure-author-charges', 'guide.disclosure-publisher', 'guide.publisher-name-address-link', 'guide.contact-person-email', 'guide.issn-displayed',
		'guide.editor-and-board', 'guide.board-listed', 'guide.board-names-affiliations', 'guide.peer-review-type-stated', 'guide.two-independent-reviewers', 'copyright.no-hybrid');
	doajpa_same(29, count($wave), 'wave size');
	foreach ($wave as $k) doajpa_same('pass', s3_status($o, $k), $k . ': ' . $o[$k]['rationale']);
	foreach (array('guide.endogeny-25-issues', 'guide.no-unapproved-metrics', 'guide.copyright-no-contradiction', 'guide.no-all-rights-reserved',
		'guide.article-dates', 'guide.persistent-identifiers', 'guide.licensing-in-full-text') as $k) doajpa_same('pass', s3_status($o, $k), $k);
	doajpa_same('warning', s3_status($o, 'transparency.website-https'), 'http fixture: recommendation warning only');
	doajpa_same(array(), array_keys(array_filter($o, function ($x) { return in_array($x['status'], array('fail', 'contradiction'), true); })), 'no fail or contradiction');
});
doajpa_test('S3-R02 Endogeny: per issue, at the 25% threshold passes; matches are listed with their articles', function () {
	list($c, $o) = s3_eval('good');
	$r = $o['guide.endogeny-25-issues'];
	doajpa_assert(strpos($r['rationale'], 'Vol. 5 No. 2 (2026): 1/4 research articles') !== false && strpos($r['rationale'], 'Vol. 5 No. 1 (2026): 1/4 research articles') !== false, 'each issue separately');
	doajpa_assert(strpos($r['rationale'], 'Thomas Becker ~ Dr. Thomas Becker (confirmed') !== false, 'match listed');
	doajpa_assert(strpos($r['rationale'], 'Editorial') === false || strpos($r['rationale'], '1 items of uncertain type') === false, 'editorial is non-research, not uncertain');
});

