doajpa_test('S3-R05 Metrics and indexing: a named non-Guide metric fails; indexing claims are listed, never classified unreliable (D-03-5)', function () {
	list($c, $o) = s3_eval('bad');
	doajpa_assert(strpos($o['guide.no-unapproved-metrics']['rationale'], 'SJIF') !== false, 'SJIF quoted');
	doajpa_same('page', $o['guide.no-unapproved-metrics']['detections'][0]['targetType'], 'page detection');
	$i = $o['guide.avoid-unreliable-indexes'];
	doajpa_same('unverifiable', $i['status'], 'indexes never judged');
	doajpa_assert(strpos($i['rationale'], 'No index is classified as unreliable') !== false && strpos($i['rationale'], '(decision D-03-5)') !== false, 'reason');
	doajpa_assert(strpos($i['rationale'], 'Index Copernicus') !== false, 'claim inventoried');
	// unnamed impact factor -> human review; a Guide-listed service -> pass
	$pages = DoajPaRuleFixture::pages('good');
	$pages['/about'][1] = str_replace('<h2>Advertising</h2>', '<p>The journal has an impact factor of 2.1 according to our own calculation for this year.</p><h2>Advertising</h2>', $pages['/about'][1]);
	$u = DoajPaRuleFixture::evaluate(DoajPaRuleFixture::context($pages, array('site' => 'good')));
	doajpa_same('for_doaj_review', $u['guide.no-unapproved-metrics']['status'], 'unnamed metric');
	$pages = DoajPaRuleFixture::pages('good');
