doajpa_test('S3-Q01 Form guide: supported answers only with verified quotes; FQ-08 never answered; conforming journal answers', function () {
	list($c, $o) = s3_eval('good');
	$fq = array();
	foreach (DoajPaRuleFixture::formGuide($c, $o) as $a) $fq[$a['questionKey']] = $a;
	doajpa_same(20, count($fq), '20 answers');
	foreach (array('FQ-01', 'FQ-03', 'FQ-04', 'FQ-05', 'FQ-06', 'FQ-07', 'FQ-10', 'FQ-11', 'FQ-12', 'FQ-13', 'FQ-14', 'FQ-15', 'FQ-16', 'FQ-17', 'FQ-18', 'FQ-19', 'FQ-20') as $k) {
		doajpa_same('supported', $fq[$k]['answerStatus'], $k . ': ' . $fq[$k]['uncertainty']);
	}
	doajpa_same(array('not_yet_assessed', null), array($fq['FQ-08']['answerStatus'], $fq['FQ-08']['answerText']), 'FQ-08');
	doajpa_same('needs_verification', $fq['FQ-02']['answerStatus'], 'start year is an estimate');
	doajpa_same('needs_verification', $fq['FQ-09']['answerStatus'], 'publisher country not verifiable');
	doajpa_assert(strpos($fq['FQ-05']['answerText'], '2049-3630') === 0 && strpos($fq['FQ-06']['answerText'], '2049-3649') === 0, 'ISSNs by label');
	doajpa_assert(strpos($fq['FQ-18']['answerText'], 'No: ') === 0, 'no APC');
	foreach ($fq as $k => $a) {
		doajpa_assert(strpos($a['uncertainty'], 'PENDING APPROVAL (D-03-2)') !== false, $k . ' labelled candidate');
		if ($a['answerStatus'] !== 'supported') continue;
		$e = $c->evidenceById($a['evidenceId']);
		doajpa_assert($e !== null && $e['verifiedEnglish'], $k . ' verified evidence');
		if (preg_match('/"([^"]{10,})"/u', $a['answerText'], $m)) {
			$found = false;
			foreach ($c->evidence() as $x) if ($x['verifiedEnglish'] && strpos($x['quote'], $m[1]) !== false) $found = true;
			doajpa_assert($found, $k . ' quoted text is verbatim evidence');
		}
	}
});
